with assessed as (select *, count(*) over (partition by reading_id) as id_count, case when reading_id > 0 and product_id is not null and product_type in ('L','M','H') and air_temperature_k > 0 and process_temperature_k > 0 and rotational_speed_rpm > 0 and torque_nm > 0 and tool_wear_min >= 0 and machine_failure in (0,1) and twf in (0,1) and hdf in (0,1) and pwf in (0,1) and osf in (0,1) and rnf in (0,1) then true else false end as valid_row from {{ ref('stg_readings') }}) select *, valid_row and id_count = 1 as accepted from assessed
